-- Seed the 52 public inspiration records from the original gallery dataset.
INSERT INTO "Inspiration" (
  "id", "slug", "title", "prompt", "category", "imagePath", "thumbnailPath", "width", "height", "modelName", "ratio", "resolutionLabel", "authorDisplayName", "sourceType", "sourceName", "sourceUrl", "licenseBasis", "isAiGenerated", "likeCount", "sortOrder", "status", "publishedAt", "createdAt", "updatedAt"
) VALUES
  ('inspiration-portrait-01', 'portrait-01', '秋日庭院里的清丽少女', '高清真人写真全身照，中景拍摄，容颜清丽脱俗，19岁清秀少女，日系清新风，浅米色、木色与绿色为主的配色，柔和自然光，冷白皮的年轻长发女子，杏色单肩系带长裙，户外平台旁有翠绿植物，背景是带卷帘的田园风房间，静谧雅致，画面清晰细腻，8K分辨率，专业摄影光源，全画幅清晰对焦。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-01.webp', '/inspiration/portrait-01.webp', 1350, 2400, '图片 4.7', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7640866760467516698', '原型演示素材，正式商用前需复核授权', TRUE, 283, 0, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-02', 'portrait-02', '深蓝礼服的优雅肖像', '真人写真，64K高清，绝色美人，气质美女，肤白细腻光滑，盘发微乱蓬松，深蓝色紧身衣服，微笑，中色模糊背景，高级项链耳环，唯美，迷人，注视着镜头浅笑', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-02.webp', '/inspiration/portrait-02.webp', 1350, 2400, '图片 5.0 Lite', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 134, 1, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-03', 'portrait-03', '秋日巷弄的随性抓拍', '日常生活快照，非常规视角构图，随手一拍。年轻女性，娇柔可爱，气质出众，眼神灵动俏皮，冷白皮通透细腻，清新淡妆。强烈阳光倾洒在头发与脸上，风吹发丝飘动，光影斑驳，边缘发光，高饱和强对比，胶片颗粒。深棕长发微卷披散，浅蓝开衫外套、白色内搭吊带，秋日巷弄石阶旁，落叶轻旋，自然光线明亮柔和，高质量人像摄影，全画幅高清。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-03.webp', '/inspiration/portrait-03.webp', 1350, 2400, '图片 4.1', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7582393020583021875', '原型演示素材，正式商用前需复核授权', TRUE, 218, 2, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-04', 'portrait-04', '莫兰迪蓝调电影人像', '绝色美人，气质美女，肤白细腻光滑，盘发微乱蓬松，深蓝色衣服，高级项链耳环，唯美迷人，注视镜头。电影级面光，光线追踪，冷白皮漫感质感，人物有最好的骨相，莫兰迪配色，高颜值网红，INS风，侧光，发丝轻飘，慵懒俏皮，东方美女，甜美氛围，构图优美，绝美角度拍摄。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-04.webp', '/inspiration/portrait-04.webp', 1350, 2400, '图片 4.0', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7620870479829617930', '原型演示素材，正式商用前需复核授权', TRUE, 196, 3, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-05', 'portrait-05', '深蓝圆领的东方少女', '真人写真，64K高清，绝色美人，气质美女，肤白细腻光滑，盘发，深蓝色圆领衣服，高级项链耳环，唯美迷人，全身照，注视镜头。电影级面光，光线追踪，莫兰迪配色，INS风，侧光，发丝轻飘，甜美少女系，东方美女，冷白皮，偶像气质，皮肤美白透亮，构图优美。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-05.webp', '/inspiration/portrait-05.webp', 1350, 2400, '图片 4.0', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7628203599662828846', '原型演示素材，正式商用前需复核授权', TRUE, 174, 4, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-06', 'portrait-06', '暖棕影棚韩系写真', '韩系氛围照片，20岁左右网红美女，妆容精致，搭配精致项链和耳环，黑色露肩上衣，背景为暖棕色低饱和磨砂质感墙面，正面柔光打光，人物面部柔和阴影过渡，摄影棚网红照质感，双手抱臂歪头，可爱笑眯眯表情，眼神灵动，胶片风格，明显颗粒感，柔光暖调。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-06.webp', '/inspiration/portrait-06.webp', 1728, 2304, '图片 4.0', '3:4', '1728 × 2304', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7639924053351927078', '原型演示素材，正式商用前需复核授权', TRUE, 242, 5, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-07', 'portrait-07', '法式窗边旗袍侧影', '8K Ultra HD超高清人物写真，绝美东方女性，鹅蛋脸，黑长直秀发自然垂落，背身侧立在白色法式竖框落地窗旁，面部侧转45度，神态清冷慵懒；身穿浅杏色修身旗袍，豆沙粉与浅绿晕染花卉印花。自然光从右侧斜射，发丝边缘有细腻轮廓光，浅景深，背景自然虚化，真实皮肤肌理，低饱和暖调，写实摄影风格。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-07.webp', '/inspiration/portrait-07.webp', 1350, 2400, '图片 4.1', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7625592109566823731', '原型演示素材，正式商用前需复核授权', TRUE, 307, 6, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-08', 'portrait-08', '薄荷绿春日花束少女', '清甜治愈的春日氛围，19岁甜美少女，冷白皮，妆容清透，暖棕色侧编辫子。白色打底衫搭配薄荷绿色V领针织开衫，米白色蕾丝蛋糕长裙，怀抱透明玻璃纸包裹的小束鲜花，站在春日都市街道边，身后明黄色围墙与嫩绿树叶形成色彩对比，暖融融的自然光，写实摄影，画面明亮温柔。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-08.webp', '/inspiration/portrait-08.webp', 1600, 2400, '图片 4.0', '2:3', '1600 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7613970153264450826', '原型演示素材，正式商用前需复核授权', TRUE, 225, 7, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-01', 'photography-01', '云雾草原的落日溪流', '远山云雾缭绕，碧绿草原一望无际，清澈溪流潺潺流淌，蓝天白云温柔治愈，落日霞光温柔绚烂，森林清新通透，光影柔和唯美，大自然原生态美景，高清细腻，氛围感拉满，极致治愈，超广角风景大片', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-01.webp', '/inspiration/photography-01.webp', 608, 1080, '图片 4.0', '9:16', '608 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7657846405393943846', '原型演示素材，正式商用前需复核授权', TRUE, 183, 8, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-02', 'photography-02', '黄金时刻的宏伟山脉', '大师级风光摄影，真实摄影质感，高分辨率，自然光线。宏伟山脉高高耸起，前景有野花，黄金时刻的暖光，大气透视自然，层次丰富。三分法构图，12mm广角镜头，极致纵深感与透视，画面通透，色彩真实，保留自然纹理与轻微胶片颗粒。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-02.webp', '/inspiration/photography-02.webp', 720, 1080, '图片 5.0 Lite', '2:3', '720 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7664183402408578354', '原型演示素材，正式商用前需复核授权', TRUE, 226, 9, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-03', 'photography-03', '炊烟村庄的金色霞光', '超高清8K画质，大师级风光摄影，电影级柔和光影质感，超广角远景构图，夕阳西下暖金色落日霞光铺满整片天空，连绵翠绿山林间静谧小村庄错落分布，屋顶升起缕缕炊烟，氛围温柔治愈，柔和逆光，自然写实色彩。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-03.webp', '/inspiration/photography-03.webp', 608, 1080, '图片 3.0', '9:16', '608 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7667320230561058075', '原型演示素材，正式商用前需复核授权', TRUE, 241, 10, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-04', 'photography-04', '蓝天草原的治愈远景', '风景摄影，治愈心灵，蓝天，白云，森林，草原，溪流，远景，阳光，丁达尔效应，高速摄影，佳能 EOS R5，壁纸，高细节，8K，电影感自然光。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-04.webp', '/inspiration/photography-04.webp', 608, 1080, '图片 5.0 Pro', '9:16', '608 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7598043171423096102', '原型演示素材，正式商用前需复核授权', TRUE, 198, 11, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-05', 'photography-05', '乌兰布统的秋日晨光', '单反风光摄影，广角镜头，远景，清晨，秋日的乌兰布统五彩滩，零星白桦树点缀画面，小河穿过薄雾缭绕的草原，羊群与骏马，朝阳刚刚露出地平线，超现实主义美景，8K超高清，高饱和度。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-05.webp', '/inspiration/photography-05.webp', 608, 1080, '图片 5.0 Lite', '9:16', '608 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7654973601874988334', '原型演示素材，正式商用前需复核授权', TRUE, 174, 12, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-06', 'photography-06', '蓝天青山的山野电影感', '治愈山野风景，蓝天白云，青山连绵，自然氛围感拉满，超清画质，电影滤镜，柔和光影，简约高级，无杂质画面，意境感十足。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-06.webp', '/inspiration/photography-06.webp', 608, 1080, '图片 5.0 Lite', '9:16', '608 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7640727386039897353', '原型演示素材，正式商用前需复核授权', TRUE, 212, 13, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-07', 'photography-07', '冰岛悬崖与飞鸟', '航拍视角，鲜绿色草坡上一个黑色人影，黄色小花点缀，右侧深色陡峭悬崖，左侧深色水面数百只白色海鸥飞舞。冰岛海边悬崖，清晨晴朗，阳光斜射草坡，氛围空灵孤寂，航拍写实摄影风格，暗色调与绿色草坡形成强烈对比，8K分辨率，DJI Mavic 3 Pro Cine航拍。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-07.webp', '/inspiration/photography-07.webp', 810, 1080, '图片 4.5', '3:4', '810 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7603813729402178854', '原型演示素材，正式商用前需复核授权', TRUE, 268, 14, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-08', 'photography-08', '雪山湖泊的橙色倒影', '8K超清自然风光照片，写实风格，画面中央为壮丽雪山，前景是平静湖泊，湖面倒映雪山，夕阳照射下雪山呈现温暖橙色，云朵也被染成橙色，整体配色蓝色、橙色和白色，宁静而壮丽，细节精致，光影逼真。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-08.webp', '/inspiration/photography-08.webp', 608, 1080, '图片 5.0 Lite', '9:16', '608 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7656190695534759195', '原型演示素材，正式商用前需复核授权', TRUE, 253, 15, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-09', 'photography-09', '墨绿色山居意境海报', '翠绿山峦主题的意境海报，葱郁绿色山坡覆盖草皮与苔藓，云雾笼罩山脊，画面下方偏右是一栋实木色小木屋。整体设计偏文艺与极简风格，墨绿色低饱和色调，保留中英文字混排与留白，传达心灵栖息在山间的宁静意境。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-09.webp', '/inspiration/photography-09.webp', 810, 1080, '图片 4.0', '3:4', '810 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7624404497539796275', '原型演示素材，正式商用前需复核授权', TRUE, 191, 16, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-photography-10', 'photography-10', '国家地理感的远方', '氛围感风景，胶片感，大师摄影作品，国家地理摄影风格，人物占十分之一画面，远景构图，真实自然光，细腻层次与故事感。', 'PHOTOGRAPHY'::"InspirationCategory", '/inspiration/photography-10.webp', '/inspiration/photography-10.webp', 720, 1080, '图片 3.1', '2:3', '720 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7651989150584917274', '原型演示素材，正式商用前需复核授权', TRUE, 165, 17, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-09', 'portrait-09', '红衣流苏的中式美人', '中式风格摄影，镜头特写，暖色调，冷白皮东方美女，极繁超长精致流苏头链，红色奢华异域服饰绣有复杂纹路，手持华丽工艺扇，中国传统大师级配色，银色点缀，神秘深邃，宁静与热烈并存，故事感与场景感。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-09.webp', '/inspiration/portrait-09.webp', 1350, 2400, '图片 4.1', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 286, 18, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-10', 'portrait-10', '暗黑蕾丝大家闺秀', '大家闺秀真人写真，冷白皮，元气妆，亭亭玉立，高雅气质，柔和灯光，黑色长发编发，黑花发饰，黑色纱制衣服，蕾丝、蝴蝶结、绫罗绸缎与水晶首饰，暗黑甜美系，半身镜头，自然光线，高细节摄影。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-10.webp', '/inspiration/portrait-10.webp', 1350, 2400, '图片 4.0', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 232, 19, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-11', 'portrait-11', '江景旁的生活感肖像', '人像摄影，冷白皮美女，瓜子脸，柔顺长发垂落肩头，修身高领长袖针织衫，身体微微前倾，表情自然害羞。江景自然色调与深色服装相互映衬，日常快照风格，近景写实，自然光影，生活气息，32K超高清细节。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-11.webp', '/inspiration/portrait-11.webp', 1350, 2400, '图片 4.0', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 208, 20, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-portrait-12', 'portrait-12', '迷雾山水中的蓝衣女性', '电影级大片，25岁亚洲美女，清纯瓜子脸，冰瓷玉肌冷白皮，深蓝色休闲针织衫。背景为迷雾山水、冷蓝天空与飘动的深蓝围巾，人物表情从容坚定，复古文艺、大气磅礴，胶片颗粒，风吹发丝的动态。', 'PORTRAIT'::"InspirationCategory", '/inspiration/portrait-12.webp', '/inspiration/portrait-12.webp', 1728, 2304, '图片 4.0', '3:4', '1728 × 2304', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 274, 21, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-01', 'anime-01', '蓝发洛丽塔萌系少女', '日式萌系动漫插画，蓝灰双马尾少女，蓝色眼眸清亮有高光，洛丽塔服饰，蝴蝶结、花朵、爱心等精致饰品，正面特写构图，手指摆出可爱姿势，浅蓝与白色主色调，清新治愈，细节丰富。', 'ANIME'::"InspirationCategory", '/inspiration/anime-01.webp', '/inspiration/anime-01.webp', 1080, 1080, '图片 3.1', '1:1', '1080 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 318, 22, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-02', 'anime-02', '高冷少女的3D厚涂肖像', '3D动漫厚涂风格，丙烯颜料质感，18岁高冷少女，深棕色单边麻花辫与空气刘海，精致清冷五官，斜挎白色针织大单肩包，柔焦、华丽通透光影，32K超高清，OC渲染，细腻发丝与肌理。', 'ANIME'::"InspirationCategory", '/inspiration/anime-02.webp', '/inspiration/anime-02.webp', 936, 1664, '图片 3.0', '9:16', '936 × 1664', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 263, 23, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-03', 'anime-03', '银白古风仙侠少年', 'CG建模，古风美少年，面部特写，冷白皮肤，凤眼清冷，灰色发丝凌乱拂面，华丽银饰从发间垂落，银白服装领口袖口精致华丽，高级朦胧梦幻氛围，写实国漫质感。', 'ANIME'::"InspirationCategory", '/inspiration/anime-03.webp', '/inspiration/anime-03.webp', 1350, 2400, '图片 4.0', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 291, 24, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-04', 'anime-04', '樱花校园的治愈少年', '动漫风格精致厚涂，少年感亚洲面孔，黑色头发，宽松高中校服外套，樱花校园与蓝天白云，自然柔光，强烈而温暖的光影对比，半厚涂CG渲染，线条流畅，治愈系高级插画。', 'ANIME'::"InspirationCategory", '/inspiration/anime-04.webp', '/inspiration/anime-04.webp', 1350, 2400, '图片 4.5', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 245, 25, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-05', 'anime-05', '白泽相伴的国漫少女', '3D国漫仙侠风格，栗色双马尾少女，发间插野花与羽毛，琥珀色杏眼，浅棕渐变草绿劲装，绣山海异兽与草木纹样，身侧跟随白泽幼兽，翠绿色自然粒子灵光，虚幻引擎电影级渲染。', 'ANIME'::"InspirationCategory", '/inspiration/anime-05.webp', '/inspiration/anime-05.webp', 1350, 2400, '图片 3.1', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 337, 26, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-06', 'anime-06', '窗边热奶茶的治愈女性', '现代2D漫剧风格，日系治愈动画质感，24岁温柔女性，奶茶棕羊毛卷，中长发齐刘海，米白针织毛衣与浅咖围巾，手捧热奶茶，暖调窗边逆光，赛璐璐平涂，低饱和暖色，单人半身立绘。', 'ANIME'::"InspirationCategory", '/inspiration/anime-06.webp', '/inspiration/anime-06.webp', 1350, 2400, '图片 5.0 Lite', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 224, 27, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-07', 'anime-07', '深紫发少女的朦胧情绪', '灵动纯美的深紫发少女，动态发丝凌乱飘动，泛光、柔焦、颗粒质感与伦勃朗光，高饱和反射折射，情绪写意，前卫视觉艺术与电影美学，CGI虚幻引擎5渲染，高级大片感。', 'ANIME'::"InspirationCategory", '/inspiration/anime-07.webp', '/inspiration/anime-07.webp', 1350, 2400, '图片 4.5', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 278, 28, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-anime-08', 'anime-08', '银发围巾的清冷特写', '3D动漫风格，浅银长发女性面部特写，眼尾淡粉，温柔湿润的眼眸略带忧郁，纤细手指轻拉浅雾灰针织围巾半遮脸颊，冷灰银白基底，柔和朦胧光影，清冷又温柔，细腻治愈。', 'ANIME'::"InspirationCategory", '/inspiration/anime-08.webp', '/inspiration/anime-08.webp', 1350, 2400, '图片 5.0 Lite', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 306, 29, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-01', 'illustration-01', '杭州地标凹版线稿海报', '杭州现代地标建筑凹版印刷线稿，粗细线结合并保留铜版雕刻痕迹，橙白色调，西湖、三潭印月、灵隐寺、莲花体育场与江南山水，以清明上河图散点透视构图，大师级插画与现代海报排版。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-01.webp', '/inspiration/illustration-01.webp', 1350, 2400, '图片 4.5', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 194, 30, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-02', 'illustration-02', '山楂山药的新中式图形', '新中式扁平渐变插画，以山楂和山药为主体，高度概括的图形，噪点肌理与色彩颗粒，纯白背景，多巴胺配色，红色与浅棕色为主，弥散渐变，年轻现代，极简先锋图形设计。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-02.webp', '/inspiration/illustration-02.webp', 1728, 2304, '图片 4.0', '3:4', '1728 × 2304', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 167, 31, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-03', 'illustration-03', '海滨小镇的冰淇淋车', '丝网印刷风格，颗粒肌理，超广角平视视角，淡蓝色海滨小镇冰淇淋车，车顶有大型冰淇淋装饰，车门口摆放绿植与桌椅，蓝白双色为主，纯扁平插画，简约构图，高饱和8K。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-03.webp', '/inspiration/illustration-03.webp', 1728, 2304, '图片 4.7', '3:4', '1728 × 2304', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 228, 32, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-04', 'illustration-04', '森林梦境的白发少年', '极繁治愈系插画，童趣涂鸦与意识流梦境，白色及腰长发、蓝色眼睛的小男孩在森林玩耍，大色块、颗粒肌理、抽象扁平表现，非对称有角度构图。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-04.webp', '/inspiration/illustration-04.webp', 1104, 1472, '图片 3.1', '3:4', '1104 × 1472', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 213, 33, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-05', 'illustration-05', '梦幻森林动物涂鸦', '极繁治愈系插画，梦幻森林动物角色，大色块与颗粒质感，色彩鲜艳饱和，童趣涂鸦和意识流自由表达，纯色背景，角落点缀手写体小字，整体色调协调。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-05.webp', '/inspiration/illustration-05.webp', 1080, 1080, '图片 4.0', '1:1', '1080 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 184, 34, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-06', 'illustration-06', '蓝色菜篮子的日系海报', '极简日系平面海报，丝网印刷与大面积留白，抽象变形的高饱和蓝色菜篮子，篮中露出樱桃，白色背景，简洁线条，90年代复古美学。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-06.webp', '/inspiration/illustration-06.webp', 1080, 1080, '图片 4.0', '1:1', '1080 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 156, 35, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-07', 'illustration-07', '我的阿勒泰三联长卷', '“我的阿勒泰”连续性三联竖版长卷，绘本与水彩插画，绿色高原、雪山、森林、绵羊和帐篷，鸟瞰视角，大色块与颗粒肌理，中英文字错落排版，简约高级，文艺留白，意识流叙事。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-07.webp', '/inspiration/illustration-07.webp', 936, 1664, '图片 3.1', '9:16', '936 × 1664', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 251, 36, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-08', 'illustration-08', '复古水彩的疯孩子', '一群充满活力的孩子，厚重色彩与复古水彩质感，超级简约手绘图，美漫风格，局部英文排版，极致细节，鲜明艺术感染力。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-08.webp', '/inspiration/illustration-08.webp', 1080, 1080, '图片 3.1', '1:1', '1080 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 203, 37, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-09', 'illustration-09', '神话山河的国风长卷', '这些极繁主义的矢量图展现出独特的艺术魅力，它们以复杂的设计风格传达出丰富的情感。通过复杂的线条、形状和色彩，勾勒出国风插画，中式美学，中国神话故事场景与现代风相融合，体现出一种现代、时尚的美感，细节丰富，电影质感。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-09.webp', '/inspiration/illustration-09.webp', 1350, 2400, '图片 4.1', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7592455799398501658', '原型演示素材，正式商用前需复核授权', TRUE, 327, 38, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-10', 'illustration-10', '白金牡丹凹版海报', '视觉海报，凹版印刷，白金图片，金色，抽象变形牡丹，牡丹5-6朵。精致的线条细致线条刻画细节，白金关系，以点线表现明暗关系，大师级排线，细致的细节，高清画质。白色背景，大片美学，大师杰作，极具视觉冲击力，获奖作品，大师级配色，大师级排版，高细节，高级感。布局协调。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-10.webp', '/inspiration/illustration-10.webp', 1350, 2400, '图片 4.5', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7610747358539730227', '原型演示素材，正式商用前需复核授权', TRUE, 284, 39, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-illustration-11', 'illustration-11', '云南地标古今图鉴', '中国现代地标建筑凹版印刷线稿，0.8mm粗线勾勒外轮廓，0.2mm细线刻画细节，保留铜版雕刻痕迹，橙白色调，大师级排版，大标题“YUNNAN DESIGN ANCIENT”，极具艺术的现代海报版式设计。主体是中国现代地标建筑：云南勐焕大金塔，金马碧鸡坊，崇圣寺三塔，兴盛大桥，大理文庙，玉龙雪山，搭配山水，树木，孔雀，大象，绿植，采用清明上河图散点透视法构图。大师级别插画，高定风插画，画面丰富饱满，充满艺术性。', 'ILLUSTRATION'::"InspirationCategory", '/inspiration/illustration-11.webp', '/inspiration/illustration-11.webp', 1350, 2400, '图片 4.5', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7589856629177240859', '原型演示素材，正式商用前需复核授权', TRUE, 301, 40, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-01', 'design-01', '山河无恙水墨字体', '文艺手写字体“山河无恙”，搭配英文小字“DESIGN BY BEIYU”，毛笔手写风格，水墨笔刷效果，笔画巧妙延长变形，黑底白字，视觉震撼的艺术字体设计。', 'DESIGN'::"InspirationCategory", '/inspiration/design-01.webp', '/inspiration/design-01.webp', 1080, 720, '图片 3.0', '3:2', '1080 × 720', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 176, 41, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-02', 'design-02', '霓虹线框实验字体海报', '瑞士平面设计风格，纯黑背景，巨型交织立体无衬线英文大字，细密渐变线条构成半透明霓虹蓝紫线框，多层错位穿插，赛博透光质感，细小白字分布于空隙，高级暗黑实验字体海报。', 'DESIGN'::"InspirationCategory", '/inspiration/design-02.webp', '/inspiration/design-02.webp', 1350, 2400, '图片 4.0', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 296, 42, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-03', 'design-03', '行为艺术解构字体', '设计“行为艺术”四个汉字，下方配英文“Performance art”，解构主义字体，笔画不规则切割与错位，线条几何化，日式极简排版，充足留白，高对比黑白，扁平矢量图形。', 'DESIGN'::"InspirationCategory", '/inspiration/design-03.webp', '/inspiration/design-03.webp', 1080, 720, '图片 4.1', '3:2', '1080 × 720', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 162, 43, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-04', 'design-04', '自由设计师街头字体', '天蓝背景与黑色创意字体“自由设计师”，搭配“电商美工设计”和英文“Design”，夸张笔画弧度，街头涂鸦风格，尖锐边缘与流畅曲线，黄色线条和星星点缀，居中排版。', 'DESIGN'::"InspirationCategory", '/inspiration/design-04.webp', '/inspiration/design-04.webp', 1728, 2304, '图片 4.6', '3:4', '1728 × 2304', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 217, 44, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-05', 'design-05', '流体能量状态视觉系统', '视觉实验风格，“emi”形状的能量状态图标，以抽象流体、光和能量变化表达stillness、flow、surge，深色背景，现代数字艺术，实验性强但整体克制高级，非UI、非品牌logo。', 'DESIGN'::"InspirationCategory", '/inspiration/design-05.webp', '/inspiration/design-05.webp', 1728, 2304, '图片 4.0', '3:4', '1728 × 2304', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 244, 45, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-06', 'design-06', '奇易居士极繁封面', '极繁主义矢量封面，复杂线条、形状和色彩勾勒“奇易居士”汉字场景，传统元素与现代风融合，下方排版中文标题与拼音，现代时尚、视觉盛宴、大师级封面设计。', 'DESIGN'::"InspirationCategory", '/inspiration/design-06.webp', '/inspiration/design-06.webp', 1350, 2400, '图片 4.1', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 231, 46, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-07', 'design-07', '心境篆刻极简标志', '简约现代logo设计，浅米色背景，艺术化中文篆书篆刻字体“心境”，中间竖排小字拼音“XINJING”，文字居中构图，四周大量留白，富有文化内涵与艺术氛围。', 'DESIGN'::"InspirationCategory", '/inspiration/design-07.webp', '/inspiration/design-07.webp', 1080, 1080, '图片 4.5', '1:1', '1080 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 188, 47, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-08', 'design-08', '绿色包装设计字体', '绿色背景与黑色创意字体“自由设计师”，搭配“包装设计”和英文“Design”，夸张笔画、街头涂鸦风格，尖锐边缘与流畅曲线，黄色线条和星星点缀，简约而有视觉冲击力。', 'DESIGN'::"InspirationCategory", '/inspiration/design-08.webp', '/inspiration/design-08.webp', 1080, 1080, '图片 4.0', '1:1', '1080 × 1080', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', NULL, '原型演示素材，正式商用前需复核授权', TRUE, 209, 48, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-09', 'design-09', '内在光辉年度视觉', '风格：内在光辉，精神肖像，高级质感，大师级设计，强烈的光影效果，电影质感，国际流行色，抽象艺术，时尚风格，意识流风格，近景，神秘感。大师级排版，右下角半透明极小小字水印“ONE FLAIR DESIGN 2026”装饰性文字。', 'DESIGN'::"InspirationCategory", '/inspiration/design-09.webp', '/inspiration/design-09.webp', 1104, 1472, '图片 3.0', '3:4', '1104 × 1472', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7667951708856667419', '原型演示素材，正式商用前需复核授权', TRUE, 276, 49, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-10', 'design-10', '粒子古风品牌主视觉', '品牌设计，大师作品，国际化风格，精致排版，简约高级，纯藏青色背景，以碧蓝色背景为主色调平面图，沉稳高级，白色与碧蓝色渐变粒子线条形成古风人物，缩小，占画面1/3。显体态线条，抽象，营造轻奢、精致质感，强调稳定与聚焦，风格偏向商业美学，简约圆润、流畅对称、精致禅意、高级质感，银灰光泽，整体极简对称。空气感，设计感，没有文字，没有数字，没有英文。', 'DESIGN'::"InspirationCategory", '/inspiration/design-10.webp', '/inspiration/design-10.webp', 1350, 2400, '图片 4.7', '9:16', '1350 × 2400', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7663394860799397130', '原型演示素材，正式商用前需复核授权', TRUE, 319, 50, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000'),
  ('inspiration-design-11', 'design-11', '燕归荷间轻奢标志', '品牌设计，大师作品，国际化风格，精致排版，简约高级，纯藏青色背景，以碧蓝色背景为主色调平面图，沉稳高级，白色与碧蓝色渐变粒子线条形成燕子，内含荷叶与半开花蕾，整体标志占画面高度三分之一。体态线条抽象，营造轻奢、精致质感，强调稳定与聚焦，简约圆润、流畅对称、精致禅意、高级质感，银灰光泽，空气感与设计感。', 'DESIGN'::"InspirationCategory", '/inspiration/design-11.webp', '/inspiration/design-11.webp', 768, 1366, '图片 5.0 Pro', '9:16', '768 × 1366', '即梦创作者', 'AI_PUBLIC_GALLERY'::"InspirationSourceType", '即梦AI公开灵感', 'https://jimeng.jianying.com/ai-tool/work-detail/7662174653191916851', '原型演示素材，正式商用前需复核授权', TRUE, 292, 51, 'PUBLISHED'::"InspirationStatus", TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000', TIMESTAMP '2026-07-31 00:00:00.000')
